      "temat": "Magiczne przedmioty i ich znaczenie – co kryje się w czarodziejskim worku?"
    },
    {
      "dzien": 2,
      "temat": "Wróżby z cieni i lampionów – odkrywamy tajemnice światła i cienia."
    },
    {
      "dzien": 3,
      "temat": "Kim będę, gdy dorosnę? – zabawy w odgadywanie przyszłych zawodów."
    },
    {
      "dzien": 4,
      "temat": "Tajemnicze wędrówki – podążamy za nitką i wskazówkami w sali."
    },
    {
      "dzien": 5,
      "temat": "Andrzejkowy bal maskowy – poznajemy i tworzymy wesołe przebrania."
    }
  ]
